 const pre=(typeof PRE!=='undefined'&&PRE.get(id)||[]).map(e=>N.get(e.p)).filter(Boolean).sort((x,y)=>(LEARN.has(y.id)?1:0)-(LEARN.has(x.id)?1:0)).slice(0,5);
